/**
* Generate a barcode image.
* 
* The `Format` is one of;
* 
* - QR = 0
* - EAN = 1
* - Code39 = 2
* - Code128 = 3
* 
* :lock: This is the safer variant to our `/barcode` endpoint, because the data moves _inside_ the POST body instead of through GET query params
* :bulb: You can use the returned `Data` in combination with `MimeType` to render the image directly, for example;
* 
* ```
*   <img src='data:{MimeType};base64,{Data}' />
* ```
*/
export interface Barcode extends RequestMessage<BarcodeResponse> {
  BackgroundHex?: string;
  BlobID?: string;
  Code: string;
  ForegroundHex?: string;
  Format?: EVAAPIBarcodesBarcode_BarcodeFormat;
  Height?: number;
  NoMargin?: boolean;
  NoText?: boolean;
  Width?: number;
}

export enum EVAAPIBarcodesBarcode_BarcodeFormat {
  QR = 0,
  EAN = 1,
  Code39 = 2,
  Code128 = 3,
}

export interface BarcodeResponse extends ResponseMessage {
  Data: string;
  MimeType: string;
}

export enum AMLAMLSystemSurveys {
  US_IRS8300 = 1,
}

export enum AMLAMLTriggerType {
  Threshold = 1,
  Scripting = 2,
  Manual = 3,
}

/**
* Cancel the AML checks on the Order. Fails any pending cash PaymentTransactions, deletes the Order's Identification (and expires its document blob), cancels the linked survey response, and clears the customer-verified flag. The flagged status is preserved.
*/
export interface CancelAMLChecksOnOrder extends RequestMessageWithEmptyResponse {
  /**
  * Entity type: Order
  */
  OrderID: number;
}

/**
* Validate all AML requirements and finalize the pending PaymentTransactions on the Order.
*/
export interface FinalizeAMLChecksOnOrder extends RequestMessage<FinalizeAMLChecksOnOrderResponse> {
  /**
  * Force the AML checks to be finalized, bypassing all rule evaluation. This skips unmet requirements (identification, customer verification, survey response) and also overrides hard-block rules (panic/manual rules, threshold rules marked Blocked). Requires the AMLOverride functionality.
  */
  Force?: boolean;
  /**
  * Entity type: Order
  */
  OrderID: number;
}

export interface FinalizeAMLChecksOnOrderResponse extends ResponseMessage {
  /**
  * Entity type: PaymentTransaction
  */
  PaymentTransactionIDs?: number[];
}

export interface AMLListConfigurationsFilter {
  CountryID?: string;
  CountrySubdivisionID?: string;
}

/**
* Flag this order to trigger manual AML checks. The order's country must have a Manual AML rule configured; otherwise the call fails with NoManualRuleConfigured. The flag is irreversible — Cancel preserves it and there is no service to clear it.
*/
export interface TriggerAMLChecksOnOrder extends RequestMessageWithEmptyResponse {
  /**
  * Entity type: Order
  */
  OrderID: number;
}

/**
* Flag the Order that the customer has been verified for AML purposes.
*/
export interface VerifyCustomerOnOrder extends RequestMessageWithEmptyResponse {
  /**
  * Entity type: Order
  */
  OrderID: number;
}

