/**
* Closes a financial period.
*/
export interface CloseFinancialPeriod extends RequestMessageWithEmptyResponse {
  /**
  * If there is an impediment to closing the period and it allows being ignored then passing the name of the impediment type in this collection will not block closing the period on that impediment. Also see `GetFinancialPeriodClosingImpediments`.
  */
  ClosingImpedimentTypesToIgnore?: string[];
  /**
  * Entity type: FinancialPeriod
  * The financial period to close. If not specified, the current financial period of the specified or current organization unit is used.
  */
  FinancialPeriodID?: number;
  /**
  * Entity type: OrganizationUnit
  * The organization unit to close the financial period for. Ignored if FinancialPeriodID is specified. If not specified, defaults to the organization unit of the logged in user.
  */
  OrganizationUnitID?: number;
}

/**
* Completes the closing of a cash journal, making the device once again unavailable for cash transactions until a new journal is opened.
* 
* This service expects a list of coins and notes, which summed up must equal the given `TotalAmount`.
* 
* If the `TotalAmount` is different from what was expected (returned as `ExpectedClosingAmount` in `StartCloseCashJournal` ) then this deviation
* must be corrected and provided through a list of corrections in the `Corrections` field.
* 
* For cash journals that either do not use or ignore cash journals, most properties will automatically be set to the expected amounts. Should you
* want to enforce validation, regardless, specify the `ForceValidation` as `true`.
* 
* Pending cash deposits need to be accounted for as well - supply their `ID`s as `PendingCashDeposits`. Do not add the `Amount` of cash deposits
* to the `TotalAmount`, as the user cannot usually verify the cash deposit content.
*/
export interface CompleteCloseCashJournal extends RequestMessageWithEmptyResponse {
  BankNotes?: Record<string,number>;
  Coins?: Record<string,number>;
  Corrections?: FinanceCompleteCloseCashJournal_CashCorrection[];
  /**
  * Entity type: Currency
  */
  CurrencyID: string;
  Data?: TAnyValue;
  /**
  * Entity type: Device
  */
  DeviceID: number;
  ForceValidation?: boolean;
  /**
  * Entity type: PaymentType
  */
  PaymentTypeID: number;
  /**
  * Entity type: CashDeposit
  */
  PendingCashDeposits?: number[];
  TotalAmount: number;
}

export interface FinanceCompleteCloseCashJournal_CashCorrection {
  Amount: number;
  Description?: string;
  /**
  * Entity type: CashCorrectionReason
  */
  ReasonID?: number;
}

/**
* Completes the opening of a cash journal. After this service has been called, it's possible to make cash transactions on this device.
* 
* This service expects a list of the coins and notes that were counted.
* 
* When the opening amount is different from last period's closing amount, it's required that a correction is provided for this difference
* in `OpeningDeviationCorrection`. This simply consists of a description and an amount.
* 
* For cash journals that either do not use or ignore cash journals, most properties will automatically be set to the expected amounts. Should you
* want to enforce validation, regardless, specify the `ForceValidation` as `true`.
* 
* Pending cash deposits need to be accounted for as well - supply their `ID`s as `PendingCashDeposits`. Do not add the `Amount` of cash deposits
* to the `TotalAmount`, as the user cannot usually verify the cash deposit content.
*/
export interface CompleteOpenCashJournal extends RequestMessageWithEmptyResponse {
  BankNotes?: Record<string,number>;
  Coins?: Record<string,number>;
  /**
  * Entity type: Currency
  */
  CurrencyID: string;
  /**
  * Entity type: Device
  */
  DeviceID: number;
  ForceValidation?: boolean;
  OpeningDeviationCorrection?: FinanceCompleteOpenCashJournal_CashCorrection;
  /**
  * Entity type: PaymentType
  */
  PaymentTypeID: number;
  /**
  * Entity type: CashDeposit
  */
  PendingCashDeposits?: number[];
  TotalAmount: number;
}

export interface FinanceCompleteOpenCashJournal_CashCorrection {
  Amount: number;
  Description: string;
  /**
  * Entity type: CashCorrectionReason
  */
  ReasonID?: number;
}

