/**
* Cancel a discount order line.
* 
* When the discount of the given line is a coupon triggerd discount, the coupon will be removed from the order.
* When the discount of the given line is a manual discount, the manual discount will be cancelled.
* When the discount of the given line is an automatic discount, the discount will be disabled on the order. To re-enable it you must call the 'EnableDisabledDiscountOnOrder' service. You can check which discount are disabled on an order by calling 'ListDisabledDiscountsOnOrder'
*/
export interface CancelDiscountOrderLine extends RequestMessage<SimpleShoppingCartResponse> {
  /**
  * Entity type: Order
  */
  OrderLineID: number;
}

/**
* Cancel a complete order or a subset of lines.
* 
* The order can be identified by an OrderID or by BackendID + BackendSystemID, the lines can be identified by an OrderLineID or by BackendID.
* 
* The result will tell you if it was successful.
*/
export interface CancelOrder extends RequestMessage<CancelOrderResponse> {
  /**
  * Try to refund the order if any cancellation was successful.
  */
  AutoRefund?: boolean;
  /**
  * Reference to the order that is being cancelled - required when `OrderID` is omitted
  */
  BackendID?: string;
  /**
  * Reference to the system from which the order originated - required when `OrderID` is omitted
  */
  BackendSystemID?: string;
  /**
  * Forcing cancellations is not recommended! Requires `ForceCancelOrder` functionality.
  * 
  *       Only use this when a normal cancellation does not work, because the exported party (warehouse) does not accept it, and they have agreed that
  *       they too will manually cancel it in their systems. This will skip all external validation and cause discrepancies in this order status and stock levels.
  */
  Force?: boolean;
  /**
  * Entity type: Order
  * ID of the order that is being cancelled - required when `BackendID` and `BackendSystemID` are omitted
  */
  OrderID?: number;
  /**
  * Entity type: OrderLine
  */
  OrderLineIDs?: number[];
  /**
  * Lines to cancel - or, if none are specified, all open lines of the order will be cancelled
  */
  OrderLines?: OrdersCancelOrder_LineToCancel[];
}

export interface OrdersCancelOrder_LineToCancel {
  /**
  * Reference to the orderline that is being cancelled - required when `OrderLineID` is omitted
  */
  BackendID?: string;
  /**
  * Entity type: OrderLine
  * ID of the orderline that is being cancelled - required when `BackendID` is omitted
  */
  OrderLineID?: number;
  /**
  * Quantity to be cancelled. If left blank the full order line will be cancelled
  */
  Quantity?: number;
}

