  /**
  * Entity type: Package
  * Optional. When only lines are provided, the PackageID can be used to create a package for all lines.
  */
  PackageID?: number;
  Packages?: ShipmentsCreateShipment_ShipmentPackage[];
  ReceiveMethod?: DataModelsShipmentReceiveMethods;
  ShipmentDate?: string;
  ShipmentIdentifiers?: ShipmentsCreateShipment_ShipmentIdentifier[];
  /**
  * Entity type: OrganizationUnit
  * Optional, will be determined based on the Order
  */
